def build_caption_fallback_index(doc):
    """Build a lookup of unclaimed caption-labeled text items, keyed by page,
    each entry holding (reading_order_index, self_ref, text).

    Docling's built-in FloatingItem.captions linking (populated during the
    standard pipeline's caption/provenance post-processing) is used first;
    this fallback only kicks in for pictures it failed to associate (e.g.
    when a stray element sits between the picture and its caption in
    reading order).
    """
    flat_items = [item for item, _level in doc.iterate_items(with_groups=False)]

    claimed_refs: set[str] = set()
    for item in flat_items:
        if isinstance(item, PictureItem):
            for cap_ref in item.captions:
                claimed_refs.add(cap_ref.cref)

    captions_by_page: dict[int, list[tuple[int, str, str]]] = {}
    for order_idx, item in enumerate(flat_items):
        if (
            isinstance(item, DocItem)
            and item.label == DocItemLabel.CAPTION
            and item.self_ref not in claimed_refs
        ):
            text = getattr(item, "text", "") or ""
            if not item.prov:
                continue
            page_no = item.prov[0].page_no
            captions_by_page.setdefault(page_no, []).append(
                (order_idx, item.self_ref, text)
            )

    picture_order_index = {
        id(item): order_idx
        for order_idx, item in enumerate(flat_items)
        if isinstance(item, PictureItem)
    }

    return flat_items, picture_order_index, captions_by_page


def nearest_fallback_caption(
    picture: PictureItem,
    picture_order_index: dict,
    captions_by_page: dict,
    used_refs: set,
) -> str:
    """Find the reading-order-nearest unclaimed caption on the same page."""
    if not picture.prov:
        return ""
    page_no = picture.prov[0].page_no
    candidates = captions_by_page.get(page_no, [])
    if not candidates:
        return ""

    pic_pos = picture_order_index.get(id(picture))
    if pic_pos is None:
        return ""

    best = None
    best_dist = None
