    flat_items = [item for item, _level in doc.iterate_items(with_groups=False)]

    # Captions can be claimed by *any* floating item (pictures, tables, ...).
    # We must exclude captions already bound elsewhere (e.g. a table caption)
    # so they are never mistakenly reassigned to a nearby picture.
    claimed_refs: set[str] = set()
    for item in flat_items:
        if isinstance(item, FloatingItem):
            for cap_ref in item.captions:
                claimed_refs.add(cap_ref.cref)

    captions_by_page: dict[int, list[tuple[int, str, str]]] = {}
    for order_idx, item in enumerate(flat_items):
        if (
            isinstance(item, DocItem)
            and item.label == DocItemLabel.CAPTION
            and item.self_ref not in claimed_refs
        ):
            text = getattr(item, "text", "") or ""
            if not item.prov:
                continue
            page_no = item.prov[0].page_no
            captions_by_page.setdefault(page_no, []).append(
                (order_idx, item.self_ref, text)
            )

    picture_order_index = {
        id(item): order_idx
        for order_idx, item in enumerate(flat_items)
        if isinstance(item, PictureItem)
    }

    return flat_items, picture_order_index, captions_by_page


